#!/usr/bin/env python3
"""Run C1 Unit08 recalibration with narrow audit extensions that avoid new target forms."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c1_unit08.py')
text=SOURCE.read_text(encoding='utf-8')
patches={
"قالت ريم إن الخطة المالية تصبح أكثر فائدة عندما تنتقل من جدول ساكن إلى نظام يوضح الافتراضات، وتسلسل الزمن، والقرارات التي تبقى مفتوحة، والمعلومة التي تستحق أن ننتظرها قبل الالتزام.''',":"قالت ريم إن الخطة المالية تصبح أكثر فائدة عندما تنتقل من جدول ساكن إلى نظام يوضح الافتراضات، وتسلسل الزمن، والقرارات التي تبقى مفتوحة، والمعلومة التي تستحق أن ننتظرها قبل الالتزام. ثم أعطت الإدارة نسخة من الخطة لمراجع لم يشارك في بنائها وطلبت منه تحديد اللحظة التي يجب عندها تغيير كل قرار. وجد بندين لا يملكان إشارة واضحة للمراجعة، فأعيد ربطهما بمؤشرات قابلة للمراقبة. جعل هذا الاختبار الخطة قابلة للتنفيذ من فريق آخر لا يعتمد على معرفة ريم الضمنية أو على تفسير شفهي يأتي بعد تغير الواقع.''',",
"قال المحلل إن مقارنة الأصول لا تصبح أعمق بكثرة الجداول، بل عندما توضح أي افتراض يحرك النتيجة، وأي خسارة لا يمكن الرجوع عنها، وأي معلومة يمكن أن تغير الالتزام قبل أن يصبح مكلفًا.''',":"قال المحلل إن مقارنة الأصول لا تصبح أعمق بكثرة الجداول، بل عندما توضح أي افتراض يحرك النتيجة، وأي خسارة لا يمكن الرجوع عنها، وأي معلومة يمكن أن تغير الالتزام قبل أن يصبح مكلفًا. وفي مراجعة مستقلة أخفى الفريق أسماء الموقعين وعرض فقط خصائص التكلفة والمرونة والوصول. لم يتغير ترتيبهم الأساسي، ما خفف احتمال أن يكون الانطباع عن المنطقة هو الذي يقود النتيجة. ثم أعادوا الأسماء وناقشوا أي معلومات محلية حقيقية يجب إضافتها، فصار السياق يدخل بصفته دليلًا قابلًا للفحص لا سمعة عامة تسبق التحليل.''',",
"قالت ليان إن تحليل التوقيت الجيد يكشف اللحظة التي يصبح فيها نجاح العقد ضغطًا على التشغيل، ويعطي الإدارة خيارات لتعديل السرعة والشروط قبل أن تتحول الفجوة إلى عجز مفاجئ.''',":"قالت ليان إن تحليل التوقيت الجيد يكشف اللحظة التي يصبح فيها نجاح العقد ضغطًا على التشغيل، ويعطي الإدارة خيارات لتعديل السرعة والشروط قبل أن تتحول الفجوة إلى عجز مفاجئ. كما اختبرت الشركة ما يحدث إذا تأخر المورد في إصدار فاتورته أو قدم خصمًا مقابل الدفع المبكر، لأن التزاماتها نفسها ليست ثابتة دائمًا. أظهر ذلك أن إدارة الفجوة لا تعتمد على العملاء فقط؛ يمكن أحيانًا تعديل توقيت الخروج كما يمكن تعديل توقيت الدخول. ومع ذلك سجلوا كلفة كل تعديل حتى لا يبدو نقل الضغط من أسبوع إلى آخر حلًا مجانيًا.''',",
"قالت سارة إن التنبؤ الجيد لا يسأل فقط «كم سترتفع الأسعار؟» بل «أي بند يتحرك أولًا، وما الذي يبقى ثابتًا، وما القرار الذي يصبح هشًا إذا جاءت السرعات بترتيب مختلف؟».''',":"قالت سارة إن التنبؤ الجيد لا يسأل فقط «كم سترتفع الأسعار؟» بل «أي بند يتحرك أولًا، وما الذي يبقى ثابتًا، وما القرار الذي يصبح هشًا إذا جاءت السرعات بترتيب مختلف؟». ثم طلبت من الفريق إعادة التحليل بعد حذف أعلى سنة من السجل التاريخي حتى يعرفوا هل النتيجة تعتمد على فترة استثنائية. بقيت بعض العلاقات الزمنية كما هي بينما تغيرت حدود أخرى، فوسعوا المجال المستخدم في القرارات الطويلة. لم يعتبروا ذلك تراجعًا؛ أصبح الافتراض أقل دقة لكنه أكثر صدقًا عن مقدار ما تسمح به البيانات.''',",
"قالت هدى إن القرار تحت معلومات ناقصة يصبح أقوى عندما يوضح ما الذي لا نعرفه، ويبحث عن خيار يتحمل عدة حالات معقولة، ويحدد أي معلومة جديدة تستحق أن تغير الحكم.''',":"قالت هدى إن القرار تحت معلومات ناقصة يصبح أقوى عندما يوضح ما الذي لا نعرفه، ويبحث عن خيار يتحمل عدة حالات معقولة، ويحدد أي معلومة جديدة تستحق أن تغير الحكم. وفي تمرين آخر طلبت من الفريق تصميم حالة صعبة معاكسة تفيد الخيار الأول بدل الثاني. ساعد ذلك على منع اختيار سيناريوهات الضغط لخدمة نتيجة مسبقة. ثم قارنوا مقدار التغير المطلوب لانقلاب القرار في الاتجاهين، فصار وصف الصمود مرتبطًا بمجال من الافتراضات لا بمجرد بقاء الخيار المفضل تحت حالة واحدة سيئة.''',",
"قالت ريم إن التنبؤ الاقتصادي الناضج ليس مسابقة للحصول على رقم أدق من الجميع. هو تصميم علاقة بين المعلومة والالتزام: ما الذي نعرفه، وما الذي لا نعرفه، وما الذي يمكننا تأجيله، ومتى تصبح المراجعة واجبة، وأي قرار يستطيع البقاء مقبولًا حتى إذا بقي المستقبل أوسع من قدرتنا على التقدير.''',":"قالت ريم إن التنبؤ الاقتصادي الناضج ليس مسابقة للحصول على رقم أدق من الجميع. هو تصميم علاقة بين المعلومة والالتزام: ما الذي نعرفه، وما الذي لا نعرفه، وما الذي يمكننا تأجيله، ومتى تصبح المراجعة واجبة، وأي قرار يستطيع البقاء مقبولًا حتى إذا بقي المستقبل أوسع من قدرتنا على التقدير. وفي المهمة الأخيرة طلبت من الطلاب ترتيب ثلاثة بحوث إضافية بحسب قيمتها للقرار، لا بحسب سهولة جمعها. اكتشفوا أن معلومة مكلفة قد تستحق الجهد إذا كانت قريبة من نقطة التحول، بينما رقم سهل التحسين لا يستحق وقتًا كبيرًا إذا ظل القرار نفسه عبر مجال واسع. بذلك أصبحت قيمة البحث نفسها جزءًا من تحليل المخاطرة.''',",
}
for old,new in patches.items():
    assert text.count(old)==1, f'expected one retry insertion point: {old[:50]!r}'
    text=text.replace(old,new)
exec(compile(text,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
